namespace sv_319597c70edb46f8b82ce75528b952e4.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);

public record NotificationPrefs(
    bool EmailNotifications,
    bool PushNotifications,
    bool WeeklyDigest,
    List<string> MutedChannels);

public record SecuritySettings(
    bool TwoFactorEnabled,
    DateTime? LastPasswordChange,
    List<ActiveSession> Sessions);

public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);

public record AppearanceSettings(
    string Theme,
    string FontSize,
    string Language,
    bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@* Vertical tab navigation for the settings dashboard *@

<nav class="settings-sidebar">
    <ul class="nav flex-column">
        @foreach (var section in Sections)
        {
            <li class="nav-item">
                <button class="nav-link @(section == ActiveSection ? "active" : "")"
                        @onclick="() => OnSectionChanged.InvokeAsync(section)">
                    <span class="sidebar-icon">@GetIcon(section)</span>
                    @section
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter, EditorRequired]
    public string ActiveSection { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@using sv_319597c70edb46f8b82ce75528b952e4.Services
@inject ISettingsService SettingsService

@if (loading)
{
    <div class="text-center p-4"><div class="spinner-border" role="status"></div></div>
}
else if (profile is not null)
{
    @if (!string.IsNullOrEmpty(statusMessage))
    {
        <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
            @statusMessage
            <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
        </div>
    }

    <h4 class="mb-4">Profile Settings</h4>

    <div class="row">
        <div class="col-md-8">
            <div class="mb-3">
                <label class="form-label fw-semibold">Display Name</label>
                <input type="text" class="form-control" @bind="displayName" />
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">Email</label>
                <input type="email" class="form-control" @bind="email" />
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">Bio</label>
                <textarea class="form-control" rows="4" @bind="bio"></textarea>
            </div>
        </div>

        <div class="col-md-4">
            <div class="text-center">
                <label class="form-label fw-semibold d-block">Avatar Preview</label>
                <div class="avatar-preview mb-2">
                    @if (!string.IsNullOrWhiteSpace(profile.AvatarUrl))
                    {
                        <img src="@profile.AvatarUrl" alt="Avatar" class="rounded-circle" style="width:100px;height:100px;object-fit:cover;" />
                    }
                    else
                    {
                        <div class="rounded-circle bg-secondary d-flex align-items-center justify-content-center text-white"
                             style="width:100px;height:100px;font-size:2rem;margin:0 auto;">
                            @(string.IsNullOrEmpty(displayName) ? "?" : displayName[0].ToString().ToUpper())
                        </div>
                    }
                </div>
                <small class="text-muted text-break">@(profile.AvatarUrl ?? "No avatar set")</small>
            </div>
        </div>
    </div>

    <div class="d-flex gap-2 mt-3">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
            @if (saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
            Save Changes
        </button>
        <button class="btn btn-outline-secondary" @onclick="Discard" disabled="@saving">
            Discard Changes
        </button>
    </div>
}

@code {
    private UserProfile? profile;
    private string displayName = "";
    private string email = "";
    private string bio = "";
    private bool loading = true;
    private bool saving;
    private string? statusMessage;
    private bool isError;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        loading = true;
        profile = await SettingsService.GetProfileAsync();
        PopulateFields();
        loading = false;
    }

    private void PopulateFields()
    {
        if (profile is null) return;
        displayName = profile.DisplayName;
        email = profile.Email;
        bio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        if (profile is null) return;
        saving = true;
        statusMessage = null;
        try
        {
            var updated = profile with { DisplayName = displayName, Email = email, Bio = bio };
            await SettingsService.SaveProfileAsync(updated);
            profile = updated;
            statusMessage = "Profile saved successfully!";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Failed to save profile: {ex.Message}";
            isError = true;
        }
        finally
        {
            saving = false;
        }
    }

    private void Discard()
    {
        PopulateFields();
        statusMessage = null;
    }
}

@using sv_319597c70edb46f8b82ce75528b952e4.Services
@inject ISettingsService SettingsService

@if (loading)
{
    <div class="text-center p-4"><div class="spinner-border" role="status"></div></div>
}
else if (prefs is not null)
{
    @if (!string.IsNullOrEmpty(statusMessage))
    {
        <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
            @statusMessage
            <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
        </div>
    }

    <h4 class="mb-4">Notification Preferences</h4>

    <div class="mb-4">
        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="emailNotif" @bind="emailNotifications" />
            <label class="form-check-label" for="emailNotif">
                <strong>Email Notifications</strong>
                <div class="text-muted small">Receive notifications via email</div>
            </label>
        </div>

        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="pushNotif" @bind="pushNotifications" />
            <label class="form-check-label" for="pushNotif">
                <strong>Push Notifications</strong>
                <div class="text-muted small">Receive browser push notifications</div>
            </label>
        </div>

        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="weeklyDigest" />
            <label class="form-check-label" for="weeklyDigest">
                <strong>Weekly Digest</strong>
                <div class="text-muted small">Receive a weekly summary email</div>
            </label>
        </div>
    </div>

    @if (allChannels.Count > 0)
    {
        <h5 class="mb-3">Muted Channels</h5>
        <div class="list-group mb-4">
            @foreach (var channel in allChannels)
            {
                var isMuted = mutedChannels.Contains(channel);
                <label class="list-group-item d-flex align-items-center gap-2">
                    <input class="form-check-input" type="checkbox" checked="@isMuted"
                           @onchange="e => ToggleChannel(channel, (bool?)e.Value ?? false)" />
                    <span>@channel</span>
                    @if (isMuted)
                    {
                        <span class="badge bg-secondary ms-auto">Muted</span>
                    }
                </label>
            }
        </div>
    }

    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
        @if (saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
        Save Preferences
    </button>
}

@code {
    private NotificationPrefs? prefs;
    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private List<string> allChannels = new();
    private bool loading = true;
    private bool saving;
    private string? statusMessage;
    private bool isError;

    protected override async Task OnInitializedAsync()
    {
        loading = true;
        prefs = await SettingsService.GetNotificationPrefsAsync();
        emailNotifications = prefs.EmailNotifications;
        pushNotifications = prefs.PushNotifications;
        weeklyDigest = prefs.WeeklyDigest;
        mutedChannels = new HashSet<string>(prefs.MutedChannels);
        // Use the channels from the loaded prefs as the full list
        allChannels = new List<string>(prefs.MutedChannels.Count > 0
            ? prefs.MutedChannels
            : []);
        loading = false;
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        saving = true;
        statusMessage = null;
        try
        {
            var updated = new NotificationPrefs(
                emailNotifications, pushNotifications, weeklyDigest,
                mutedChannels.ToList());
            await SettingsService.SaveNotificationPrefsAsync(updated);
            prefs = updated;
            statusMessage = "Preferences saved successfully!";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Failed to save preferences: {ex.Message}";
            isError = true;
        }
        finally
        {
            saving = false;
        }
    }
}

@using sv_319597c70edb46f8b82ce75528b952e4.Services
@inject ISettingsService SettingsService

<div class="card mb-4">
    <div class="card-header d-flex align-items-center justify-content-between"
         role="button" @onclick="() => expanded = !expanded">
        <strong>Change Password</strong>
        <span>@(expanded ? "▲" : "▼")</span>
    </div>

    @if (expanded)
    {
        <div class="card-body">
            @if (!string.IsNullOrEmpty(statusMessage))
            {
                <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
                    @statusMessage
                    <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
                </div>
            }

            <div class="mb-3">
                <label class="form-label fw-semibold">Current Password</label>
                <input type="password" class="form-control" @bind="currentPassword" />
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">New Password</label>
                <input type="password" class="form-control" @bind="newPassword" />
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">Confirm New Password</label>
                <input type="password" class="form-control @(confirmMismatch ? "is-invalid" : "")"
                       @bind="confirmPassword" />
                @if (confirmMismatch)
                {
                    <div class="invalid-feedback">Passwords do not match.</div>
                }
            </div>

            <button class="btn btn-warning" @onclick="UpdatePasswordAsync" disabled="@saving">
                @if (saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Update Password
            </button>
        </div>
    }
</div>

@code {
    private bool expanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool saving;
    private string? statusMessage;
    private bool isError;

    private bool confirmMismatch => !string.IsNullOrEmpty(confirmPassword) && newPassword != confirmPassword;

    private async Task UpdatePasswordAsync()
    {
        statusMessage = null;

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            statusMessage = "Please fill in all password fields.";
            isError = true;
            return;
        }

        if (newPassword != confirmPassword)
        {
            statusMessage = "New password and confirmation do not match.";
            isError = true;
            return;
        }

        saving = true;
        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            statusMessage = "Password updated successfully!";
            isError = false;
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
        }
        catch (Exception ex)
        {
            statusMessage = $"Failed to update password: {ex.Message}";
            isError = true;
        }
        finally
        {
