@* Vertical tab navigation for the settings dashboard *@

<nav class="settings-sidebar">
    <ul class="nav flex-column">
        @foreach (var section in Sections)
        {
            <li class="nav-item">
                <button class="nav-link @(section == ActiveSection ? "active" : "")"
                        @onclick="() => OnSectionChanged.InvokeAsync(section)">
                    <span class="sidebar-icon">@GetIcon(section)</span>
                    @section
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter, EditorRequired]
    public string ActiveSection { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@using sv_319597c70edb46f8b82ce75528b952e4.Services
@inject ISettingsService SettingsService

@if (loading)
{
    <div class="text-center p-4"><div class="spinner-border" role="status"></div></div>
}
else if (profile is not null)
{
    @if (!string.IsNullOrEmpty(statusMessage))
    {
        <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
            @statusMessage
            <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
        </div>
    }

    <h4 class="mb-4">Profile Settings</h4>

    <div class="row">
        <div class="col-md-8">
            <div class="mb-3">
                <label class="form-label fw-semibold">Display Name</label>
                <input type="text" class="form-control" @bind="displayName" />
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">Email</label>
                <input type="email" class="form-control" @bind="email" />
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">Bio</label>
                <textarea class="form-control" rows="4" @bind="bio"></textarea>
            </div>
        </div>

        <div class="col-md-4">
            <div class="text-center">
                <label class="form-label fw-semibold d-block">Avatar Preview</label>
                <div class="avatar-preview mb-2">
                    @if (!string.IsNullOrWhiteSpace(profile.AvatarUrl))
                    {
                        <img src="@profile.AvatarUrl" alt="Avatar" class="rounded-circle" style="width:100px;height:100px;object-fit:cover;" />
                    }
                    else
                    {
                        <div class="rounded-circle bg-secondary d-flex align-items-center justify-content-center text-white"
                             style="width:100px;height:100px;font-size:2rem;margin:0 auto;">
                            @(string.IsNullOrEmpty(displayName) ? "?" : displayName[0].ToString().ToUpper())
                        </div>
                    }
                </div>
                <small class="text-muted text-break">@(profile.AvatarUrl ?? "No avatar set")</small>
            </div>
        </div>
    </div>

    <div class="d-flex gap-2 mt-3">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
            @if (saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
            Save Changes
        </button>
        <button class="btn btn-outline-secondary" @onclick="Discard" disabled="@saving">
            Discard Changes
        </button>
    </div>
}

@code {
    private UserProfile? profile;
    private string displayName = "";
    private string email = "";
    private string bio = "";
    private bool loading = true;
    private bool saving;
    private string? statusMessage;
    private bool isError;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        loading = true;
        profile = await SettingsService.GetProfileAsync();
        PopulateFields();
        loading = false;
    }

    private void PopulateFields()
    {
        if (profile is null) return;
        displayName = profile.DisplayName;
        email = profile.Email;
        bio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        if (profile is null) return;
        saving = true;
        statusMessage = null;
        try
        {
            var updated = profile with { DisplayName = displayName, Email = email, Bio = bio };
            await SettingsService.SaveProfileAsync(updated);
            profile = updated;
            statusMessage = "Profile saved successfully!";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Failed to save profile: {ex.Message}";
            isError = true;
        }
        finally
        {
            saving = false;
        }
    }

    private void Discard()
    {
        PopulateFields();
        statusMessage = null;
    }
}

