@using sv_319597c70edb46f8b82ce75528b952e4.Services
@inject ISettingsService SettingsService

@if (loading)
{
    <div class="text-center p-4"><div class="spinner-border" role="status"></div></div>
}
else if (security is not null)
{
    @if (!string.IsNullOrEmpty(statusMessage))
    {
        <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
            @statusMessage
            <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
        </div>
    }

    <h4 class="mb-4">Security Settings</h4>

    <ChangePasswordPanel />

    <div class="card mb-4">
        <div class="card-body">
            <div class="d-flex align-items-center justify-content-between">
                <div>
                    <strong>Two-Factor Authentication</strong>
                    <div class="text-muted small">Add an extra layer of security to your account</div>
                </div>
                <div class="d-flex align-items-center gap-2">
                    <span class="badge @(security.TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(security.TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                    <div class="form-check form-switch mb-0">
                        <input class="form-check-input" type="checkbox" checked="@security.TwoFactorEnabled" disabled
                               title="Contact your administrator to change 2FA settings" />
                    </div>
                </div>
            </div>
            @if (security.LastPasswordChange.HasValue)
            {
                <div class="text-muted small mt-2">
                    Last password change: @security.LastPasswordChange.Value.ToString("MMMM d, yyyy")
                </div>
            }
        </div>
    </div>

    <h5 class="mb-3">Active Sessions</h5>
    @if (security.Sessions.Count == 0)
    {
        <p class="text-muted">No active sessions found.</p>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-hover align-middle">
                <thead class="table-light">
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in security.Sessions)
                    {
                        var isCurrent = session == security.Sessions[0];
                        <tr>
                            <td>
                                @session.Device
                                @if (isCurrent)
                                {
                                    <span class="badge bg-primary ms-1">Current</span>
                                }
                            </td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("MMM d, yyyy h:mm tt")</td>
                            <td class="text-end">
                                @if (!isCurrent)
                                {
                                    <button class="btn btn-outline-danger btn-sm"
                                            @onclick="() => ConfirmRevoke(session)">
                                        Revoke
                                    </button>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }

    @* Revoke confirmation dialog *@
    @if (sessionToRevoke is not null)
    {
        <div class="modal-backdrop fade show"></div>
        <div class="modal fade show d-block" tabindex="-1" role="dialog">
            <div class="modal-dialog modal-dialog-centered" role="document">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">Revoke Session</h5>
                        <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                    </div>
                    <div class="modal-body">
                        <p>
                            Are you sure you want to revoke the session on
                            <strong>@sessionToRevoke.Device</strong> from
                            <strong>@sessionToRevoke.Location</strong>?
                        </p>
                        <p class="text-muted small">This will sign out that device immediately.</p>
                    </div>
                    <div class="modal-footer">
                        <button class="btn btn-secondary" @onclick="CancelRevoke" disabled="@revoking">Cancel</button>
                        <button class="btn btn-danger" @onclick="RevokeAsync" disabled="@revoking">
                            @if (revoking) { <span class="spinner-border spinner-border-sm me-1"></span> }
                            Revoke Session
                        </button>
                    </div>
                </div>
            </div>
        </div>
    }
}

@code {
    private SecuritySettings? security;
    private bool loading = true;
    private ActiveSession? sessionToRevoke;
    private bool revoking;
    private string? statusMessage;
    private bool isError;

    protected override async Task OnInitializedAsync()
    {
        await LoadAsync();
    }

    private async Task LoadAsync()
    {
        loading = true;
        security = await SettingsService.GetSecuritySettingsAsync();
        loading = false;
    }

    private void ConfirmRevoke(ActiveSession session) => sessionToRevoke = session;

    private void CancelRevoke() => sessionToRevoke = null;

    private async Task RevokeAsync()
    {
        if (sessionToRevoke is null) return;
        revoking = true;
        statusMessage = null;
        try
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            statusMessage = $"Session on {sessionToRevoke.Device} has been revoked.";
            isError = false;
            sessionToRevoke = null;
            security = await SettingsService.GetSecuritySettingsAsync();
        }
        catch (Exception ex)
        {
            statusMessage = $"Failed to revoke session: {ex.Message}";
            isError = true;
        }
        finally
        {
            revoking = false;
        }
    }
}

