@using sv_319597c70edb46f8b82ce75528b952e4.Services
@inject ISettingsService SettingsService

@if (loading)
{
    <div class="text-center p-4"><div class="spinner-border" role="status"></div></div>
}
else
{
    @if (!string.IsNullOrEmpty(statusMessage))
    {
        <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
            @statusMessage
            <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
        </div>
    }

    <h4 class="mb-4">Appearance Settings</h4>

    <div class="row">
        <div class="col-md-6">
            <div class="mb-4">
                <label class="form-label fw-semibold">Theme</label>
                <div class="d-flex gap-3">
                    @foreach (var t in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme"
                                   id="@($"theme-{t}")" value="@t" checked="@(theme == t)"
                                   @onchange="() => theme = t" />
                            <label class="form-check-label" for="@($"theme-{t}")">@t</label>
                        </div>
                    }
                </div>
            </div>

            <div class="mb-4">
                <label class="form-label fw-semibold">Font Size</label>
                <div class="d-flex gap-3">
                    @foreach (var fs in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="fontSize"
                                   id="@($"fs-{fs}")" value="@fs" checked="@(fontSize == fs)"
                                   @onchange="() => fontSize = fs" />
                            <label class="form-check-label" for="@($"fs-{fs}")">@fs</label>
                        </div>
                    }
                </div>
            </div>

            <div class="mb-4">
                <label class="form-label fw-semibold" for="language-select">Language</label>
                <select class="form-select" id="language-select" @bind="language">
                    <option value="en">English</option>
                    <option value="es">Español</option>
                    <option value="fr">Français</option>
                    <option value="de">Deutsch</option>
                    <option value="ja">日本語</option>
                    <option value="zh">中文</option>
                </select>
            </div>

            <div class="mb-4">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="compactMode" />
                    <label class="form-check-label" for="compactMode">
                        <strong>Compact Mode</strong>
                        <div class="text-muted small">Reduce spacing and padding throughout the UI</div>
                    </label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@saving">
                @if (saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save
            </button>
        </div>

        <div class="col-md-6">
            <label class="form-label fw-semibold">Live Preview</label>
            <div class="border rounded @PreviewClasses" style="@PreviewStyle">
                <div class="@(compactMode ? "p-2" : "p-3") border-bottom" style="font-weight:600;">
                    Preview Header
                </div>
                <div class="@(compactMode ? "p-2" : "p-3")">
                    <p class="@(compactMode ? "mb-1" : "mb-2")">
                        This is how your content will look with the selected settings.
                    </p>
