+::deep .settings-sidebar {
+    background: #f8f9fa;
+    border-radius: 0.5rem;
+    padding: 0.5rem;
+    position: sticky;
+    top: 1rem;
+}
+
+::deep .settings-sidebar .nav-link {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    padding: 0.75rem 1rem;
+    border: none;
+    background: transparent;
+    border-radius: 0.375rem;
+    color: #495057;
+    font-weight: 500;
+    width: 100%;
+    text-align: left;
+    cursor: pointer;
+    transition: background-color 0.15s, color 0.15s;
+}
+
+::deep .settings-sidebar .nav-link:hover {
+    background-color: #e9ecef;
+    color: #212529;
+}
+
+::deep .settings-sidebar .nav-link.active {
+    background-color: #0d6efd;
+    color: #fff;
+}
+
+::deep .sidebar-icon {
+    font-size: 1.1rem;
+}
+
